import React, { useEffect, useMemo, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { inventoryAPI, upgradesAPI, dashboardAPI, api } from '../services/api';
import ImageWithFallback from '../components/ImageWithFallback';

const UpgradePage = () => {
  const { updateBalance } = useAuth();
  const [inventory, setInventory] = useState([]);
  const [allItems, setAllItems] = useState([]);
  const [sourceId, setSourceId] = useState(null);
  const [targetId, setTargetId] = useState(null);
  const [result, setResult] = useState(null);
  const [balance, setBalance] = useState(0);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);

  const refresh = async () => {
    const [inv, items, bal] = await Promise.all([inventoryAPI.getInventory(), api.get('/items/'), dashboardAPI.getBalance()]);
    setInventory(inv.data); setAllItems(items.data); setBalance(Number(bal.data.balance || 0));
  };

  useEffect(() => { refresh().catch(console.error).finally(() => setLoading(false)); }, []);

  const source = inventory.find((row) => row.item_id === sourceId)?.item || null;
  const targets = useMemo(() => source ? allItems.filter((item) => item.id !== source.id && Number(item.virtual_value) > Number(source.virtual_value)) : [], [allItems, source]);
  const target = targets.find((item) => item.id === targetId) || null;
  const chance = source && target ? Math.min(95, Math.max(1, Number(source.virtual_value) / Number(target.virtual_value) * 100)) : 0;

  const selectSource = (id) => { setSourceId(id); setTargetId(null); setResult(null); };

  const runUpgrade = async () => {
    if (!source || !target || busy) return;
    setBusy(true); setResult(null);
    try {
      const response = await upgradesAPI.performUpgrade({ original_item_id: source.id, target_item_id: target.id });
      setResult(response.data);
      await refresh();
      await updateBalance();
    } catch (error) {
      alert(error.response?.data?.detail || 'Upgrade failed.');
    } finally { setBusy(false); }
  };

  if (loading) return <div className="container py-5 text-center"><div className="spinner-border text-danger" /></div>;

  return (
    <div className="container py-4 upgrade-page">
      <div className="upgrade-hero">
        <div><span className="upgrade-kicker">WELLCASE LAB</span><h1>UPGRADE</h1><p>Risk one skin to chase a higher-value drop.</p></div>
        <div className="upgrade-balance"><span>BALANCE</span><strong>{balance.toLocaleString()} €</strong></div>
      </div>

      <div className="upgrade-machine">
        <section className="upgrade-panel">
          <div className="panel-title"><span>01</span><div><h3>Your item</h3><small>Select one item from your inventory</small></div></div>
          <div className="upgrade-grid">
            {inventory.length ? inventory.map((row) => {
              const active = sourceId === row.item_id;
              return <button key={row.id} className={`upgrade-item ${active ? 'selected' : ''}`} onClick={() => selectSource(row.item_id)}>
                <ImageWithFallback src={row.item?.image_url} alt={row.item?.name} className="upgrade-item-image" />
                <strong>{row.item?.name}</strong><span>{Number(row.item?.virtual_value || 0).toLocaleString()} €</span><em>x{row.quantity}</em>
              </button>;
            }) : <div className="upgrade-empty">Your inventory is empty.</div>}
          </div>
        </section>

        <div className="upgrade-arrow">→</div>

        <section className="upgrade-panel target-panel">
          <div className="panel-title"><span>02</span><div><h3>Target item</h3><small>{source ? 'Only higher-value items are shown' : 'Select a source item first'}</small></div></div>
          <div className="upgrade-grid">
            {targets.length ? targets.map((item) => {
              const active = targetId === item.id;
              const itemChance = Math.min(95, Math.max(1, Number(source.virtual_value) / Number(item.virtual_value) * 100));
              return <button key={item.id} className={`upgrade-item ${active ? 'selected' : ''}`} onClick={() => setTargetId(item.id)}>
                <ImageWithFallback src={item.image_url} alt={item.name} className="upgrade-item-image" />
                <strong>{item.name}</strong><span>{Number(item.virtual_value).toLocaleString()} €</span><em>{itemChance.toFixed(1)}% chance</em>
              </button>;
            }) : <div className="upgrade-empty">{source ? 'No higher-value target available.' : 'Choose your item on the left.'}</div>}
          </div>
        </section>
      </div>

      <section className="upgrade-action">
        <div className="upgrade-preview">
          <div><small>FROM</small><strong>{source?.name || '—'}</strong></div><div className="chance-ring">{chance ? `${chance.toFixed(1)}%` : '—'}<small>WIN</small></div><div className="text-end"><small>TO</small><strong>{target?.name || '—'}</strong></div>
        </div>
        <button className="upgrade-cta" disabled={!source || !target || busy} onClick={runUpgrade}>{busy ? 'UPGRADING…' : 'UPGRADE NOW'}</button>
      </section>

      {result && <section className={`upgrade-result ${result.was_successful ? 'success' : 'failed'}`}><div className="result-icon">{result.was_successful ? '✓' : '×'}</div><div><span>{result.was_successful ? 'UPGRADE SUCCESSFUL' : 'UPGRADE FAILED'}</span><h3>{result.was_successful ? `You received ${target?.name || 'the target item'}` : `You lost ${source?.name || 'your item'}`}</h3><p>Final chance: {Number(result.success_chance).toFixed(1)}%</p></div><button onClick={() => { setResult(null); setSourceId(null); setTargetId(null); }}>NEW UPGRADE</button></section>}
    </div>
  );
};

export default UpgradePage;
